        self.regs = {
            0x00: 0x8000,  # TEMP
            0x01: 0x0220,  # CONFIG
            0x02: 0x6000,  # THIGH
            0x03: 0x8000,  # TLOW
            0x04: 0x0000,  # EEPROM_UL
            0x05: 0x0000,  # EEPROM1
            0x06: 0x0000,  # EEPROM2
            0x07: 0x0000,  # TEMP_OFFSET
            0x08: 0x0000,  # EEPROM3
            0x0F: 0x0117   # DEVICE_ID
        }

    def read_register(self, addr: int, nbytes: int = 2) -> int:
        if nbytes == 1:
            return (self.regs[addr] & 0xFF00) >> 8
        else:
            return self.regs[addr]

    def write_register(self, addr: int, data: int, nbytes: int = 2) -> None:
        if nbytes == 1:
            self.regs[addr] = (self.regs[addr] & 0x00FF) | (data << 8)
        else:
            self.regs[addr] = data

        # CONFIG register fields with read_as attribute should always read back that value
        if addr == 0x01:
            if (data & 0x1000) == 0x1000:
                self.regs[0x01] |= 0x1000  # set HIGH_ALERT
            if (data & 0x0800) == 0x0800:
                self.regs[0x01] |= 0x0800  # set LOW_ALERT
            if (data & 0x0400) == 0x0400:
                self.regs[0x01] |= 0x0400  # set DATA_READY
            if (data & 0x0200) == 0x0200:
                self.regs[0x01] |= 0x0200  # set EEPROM_BUSY

