class TMP117_Simulator(BaseVirtualSensor):
    def __init__(self):
        super().__init__()
        self.regs = {
            0x00: 0x8000,  # TEMP
            0x01: 0x0220,  # CONFIG
            0x02: 0x6000,  # THIGH
            0x03: 0x8000,  # TLOW
